/* Lazily built key→entry maps. Repeated `indexOf` scans of 704 tribal areas
   per mouse move is the kind of thing that is fine until it is not. */
const INDEX = new Map();

function indexFor(kind) {
  if (!INDEX.has(kind)) {
    const list = AOIS[kind];
    INDEX.set(kind, list ? new Map(list.map((e) => [e.key, e])) : null);
  }
  return INDEX.get(kind);
}

/** The entry for one AOI, or null if the kind or the key is unknown. */
export function aoiEntry(kind, key) {
  return indexFor(kind)?.get(String(key)) ?? null;
}

/**
 * The AOI's label as a person reads it:
 * "Montana", "Fort Peck Indian Reservation", "North Central (MT)". Unknown
 * keys come back as themselves rather than as "undefined", so a stale URL
 * degrades to something legible.
 */
export function aoiLabel(kind, key) {
  const entry = aoiEntry(kind, key);
  if (!entry) return String(key);
  if (kind === 'climdiv') return `${entry.name} (${entry.state})`;
  return entry.name;
}
